def detect_good_v2(code: str) -> str:
    try:
        tree = ast.parse(code)
        good_patterns = [
            "def {}({}) -> {}:".format(n, args, ret)
            for n, body in ast.walk(tree)
            if isinstance(body, ast.FunctionDef)
            and (args := ', '.join(arg.id for arg in body.args.args))
            and (ret := body.returns and f"{body.returns.id}" or "None")
            and len(body.body) == 1 and isinstance(body.body[0], ast.Return)
        ]
        return f"Good patterns: {len(good_patterns)} (e.g., {', '.join(good_patterns[:3])})"
    except:
        return "No good patterns detected"

