def detect_good(code: str) -> str:
    try:
        tree = ast.parse(code)
        good_indicators = []
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.ClassDef)):
                if node.decorator_list and any(isinstance(d, ast.Name) and d.id in ('property', 'staticmethod', 'classmethod') for d in node.decorator_list):
                    good_indicators.append(f"{node.name} ({'class' if isinstance(node, ast.ClassDef) else 'func'})")
            elif isinstance(node, ast.Assign) and any(isinstance(target, ast.Name) and target.id in ('__init__', '__str__', '__repr__') for target in node.targets):
                good_indicators.append(f"Magic method {node.value.id if isinstance(node.value, ast.Name) else 'defined'}")
        return f"Good patterns: {', '.join(good_indicators) if good_indicators else 'None found'}"
    except:
        return "No good patterns detected (parsing error)"
